SELECT fn_cp_import_case('deonto-photographie-dans-un-service', '{"slug": "deonto-photographie-dans-un-service", "title": "La photo de groupe montre un écran resté allumé", "theme_slug": "deontologie", "difficulty": "facile", "is_free": true, "is_published": true, "status": "published", "year": 2026, "month": "Juillet", "total_points": 15, "estimated_minutes": 20, "situation_text": "Il est 13 heures. Dans les locaux du service, une photo de groupe prise pour marquer un événement convivial entre collègues révèle en arrière-plan un écran d''ordinateur resté allumé sur lequel des informations sensibles restent potentiellement visibles, cette intention initialement anodine de cette photographie créant une fuite involontaire par simple négligence plutôt que par malveillance délibérée de quiconque. Cette configuration, où cette conséquence potentiellement grave résulte d''une négligence et non d''une intention de nuire, nécessite de faire supprimer cette photographie et de signaler cette fuite potentielle avant toute diffusion de ce cliché.\n\nCette situation, caractéristique des incidents de sécurité qui naissent d''une négligence banale plutôt que d''un acte intentionnel, impose une réaction rapide pour limiter les conséquences de cette négligence avant qu''elle ne produise des effets plus graves par une diffusion incontrôlée.\n\nCette configuration nécessite de faire supprimer cette photographie et de signaler cette fuite potentielle, cette double exigence restant essentielle pour limiter les conséquences de cette négligence avant toute diffusion incontrôlée.", "questions": [{"position": 1, "max_points": 5, "label": "Comment faites-vous supprimer cette photographie avant toute diffusion incontrôlée ?", "hint": "Cette suppression doit intervenir rapidement, cette action restant nécessaire pour éviter que cette fuite involontaire ne produise des conséquences plus graves par une diffusion non maîtrisée.", "perfect": "Je demande immédiatement la suppression de cette photographie, cette rapidité restant nécessaire pour éviter toute diffusion incontrôlée de ces informations sensibles visibles.\n\nJe reste attentive à vérifier que cette suppression concerne l''ensemble des copies éventuelles de cette photographie, cette exhaustivité restant importante pour garantir l''efficacité de cette action.\n\nJe reste factuelle avec les collègues présents sur cette photo sur les raisons de cette suppression nécessaire, cette explication restant utile pour leur compréhension.\n\nJe reste attentive à agir avant tout partage de cette photographie sur des messageries ou réseaux sociaux, cette urgence restant appropriée compte tenu du risque de diffusion rapide.", "points": [{"position": 1, "label": "Demander immédiatement la suppression de cette photographie", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : rapidité évitant une diffusion incontrôlée.", "groups": [{"position": 1, "keywords": ["photographie supprimée", "diffusion évitée", "informations sensibles"]}]}, {"position": 2, "label": "Vérifier que cette suppression concerne l''ensemble des copies éventuelles", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Exhaustivité garantissant l''efficacité.", "groups": [{"position": 1, "keywords": ["copies vérifiées", "exhaustivité assurée", "efficacité garantie"]}]}, {"position": 3, "label": "Rester factuelle avec les collègues sur les raisons de cette suppression", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Explication utile pour leur compréhension.", "groups": [{"position": 1, "keywords": ["raisons expliquées", "collègues informés", "compréhension assurée"]}]}, {"position": 4, "label": "Agir avant tout partage sur messageries ou réseaux sociaux", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Urgence compte tenu du risque de diffusion rapide.", "groups": [{"position": 1, "keywords": ["partage anticipé", "urgence reconnue", "diffusion rapide"]}]}]}, {"position": 2, "max_points": 5, "label": "Comment signalez-vous cette fuite potentielle d''informations sensibles ?", "hint": "Ce signalement doit intervenir rapidement, cette transmission restant nécessaire pour permettre une appréciation appropriée de la gravité de cette fuite involontaire par les personnes compétentes.", "perfect": "Je signale cette fuite potentielle à ma hiérarchie, cette transmission restant nécessaire malgré le caractère involontaire de cette négligence constatée.\n\nJe reste factuelle sur la nature des informations qui étaient visibles sur cet écran, cette précision restant utile pour apprécier la gravité réelle de cette fuite potentielle.\n\nJe reste attentive à ne pas dramatiser ni minimiser cette situation, cette mesure restant appropriée pour une appréciation juste par les personnes compétentes.\n\nJe reste disponible pour toute précision complémentaire, cette réactivité restant utile pour permettre un traitement approprié de cette négligence constatée.", "points": [{"position": 1, "label": "Signaler cette fuite potentielle à la hiérarchie", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : transmission malgré le caractère involontaire.", "groups": [{"position": 1, "keywords": ["fuite signalée", "négligence constatée", "hiérarchie informée"]}]}, {"position": 2, "label": "Rester factuelle sur la nature des informations visibles", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Précision utile pour apprécier la gravité.", "groups": [{"position": 1, "keywords": ["informations précisées", "gravité appréciée", "nature décrite"]}]}, {"position": 3, "label": "Ne pas dramatiser ni minimiser cette situation", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Mesure pour une appréciation juste.", "groups": [{"position": 1, "keywords": ["mesure appliquée", "appréciation juste", "situation équilibrée"]}]}, {"position": 4, "label": "Rester disponible pour toute p